import{_ as p,o as a,c as e,a2 as E}from"./chunks/framework.Bg-Zxr5O.js";const t=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/SORT-VARIABLES.md","filePath":"manual-zh/SORT-VARIABLES.md","lastUpdated":1785684581000}'),L={name:"manual-zh/SORT-VARIABLES.md"};function R(S,A,I,r,T,B){return a(),e("div",null,[...A[0]||(A[0]=[E(`<h3 id="_11-5-sort-variables" tabindex="-1">11.5 SORT VARIABLES <a class="header-anchor" href="#_11-5-sort-variables" aria-label="Permalink to &quot;11.5 SORT VARIABLES&quot;">​</a></h3><p><code>SORT VARIABLES</code> 根据所选的排序键对活动数据集字典中的变量重新排序。</p><pre><code>SORT VARIABLES [BY]
    (NAME | TYPE | FORMAT | LABEL | VALUES | MISSING | MEASURE
     | ROLE | COLUMNS | ALIGNMENT | ATTRIBUTE name)
    [(D)].
</code></pre><p>主要指定项是下列标识符之一，它决定变量如何排序：</p><p>NAME</p><p>按变量名排序，不区分大小写。不过，当变量名只在末尾的数字上不同时，会按数值排序。例如，<code>VAR5</code> 排在 <code>VAR400</code> 之前，尽管 ‘4’ 在 ‘5’ 之前。</p><p>TYPE</p><p>数值变量排在字符串变量之前，较短的字符串变量排在较长的字符串变量之前。</p><p>FORMAT</p><p>按打印格式对变量分组；在同一格式内，较窄的格式排在较宽的格式之前；格式和宽度相同时，小数位数较少的排在小数位数较多的之前。参见 <a href="./FORMATS">FORMATS</a>。</p><p>LABEL</p><p>没有变量标签的变量排在有变量标签的变量之前。参见 <a href="./VARIABLE-LABELS">VARIABLE LABELS</a>。</p><p>VALUES</p><p>没有值标签的变量排在有值标签的变量之前。参见 <a href="./VALUE-LABELS">VALUE LABELS</a>。</p><p>MISSING</p><p>没有缺失值的变量排在有缺失值的变量之前。参见 <a href="./MISSING-VALUES">MISSING VALUES</a>。</p><p>MEASURE</p><p>名义变量排在最先，其次是顺序变量，再次是标度变量。参见 <a href="./VARIABLE-LEVEL">VARIABLE LEVEL</a>。</p><p>ROLE</p><p>按变量的角色分组。参见 <a href="./VARIABLE-ROLE">VARIABLE ROLE</a>。</p><p>COLUMNS</p><p>按显示宽度升序排序。参见 <a href="./VARIABLE-WIDTH">VARIABLE WIDTH</a>。</p><p>ALIGNMENT</p><p>按变量的对齐方式排序，先是左对齐，然后右对齐，然后居中。参见 <a href="./VARIABLE-ALIGNMENT">VARIABLE ALIGNMENT</a>。</p><p>ATTRIBUTE name</p><p>按变量 name 属性的第一个取值排序。没有该属性的变量排在最前。参见 <a href="./VARIABLE-ATTRIBUTE">VARIABLE ATTRIBUTE</a>。</p><p>只能指定一个排序标准。排序是“稳定的”，因此要按多个标准排序，可以执行多次排序。例如，下面会主要基于对齐方式排序，对齐方式相同的变量再按显示宽度排序：</p><pre><code>SORT VARIABLES BY COLUMNS.
SORT VARIABLES BY ALIGNMENT.
</code></pre><p>指定 <code>(D)</code> 可反转排序顺序。</p>`,29)])])}const V=p(L,[["render",R]]);export{t as __pageData,V as default};
